<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Missing Dice — Roll a D8</title>
<style>
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    min-height: 100%;
    background: #f7f5f2;
    color: #111;
    font-family: "Courier New", Courier, monospace;
  }

  body {
