  }

  .brand img {
    display: block;
    width: 45px;
    height: 45px;
    object-fit: cover;
  }

  .header-right {
    display: flex;
    align-items: center;
    gap: 20px;
    height: 100%;
  }

  .coffee {
    color: #111;
    font-size: 17px;
    text-decoration: underline;
    text-decoration-style: dotted;
  }

  .modes {
    height: 68px;
    min-width: 175px;
    padding: 0 8px 0 16px;
    border: 1px solid #d0c5bc;
    background: #f2ede8;
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-weight: bold;
    font-size: 16px;
  }

  .down {
    width: 32px;
    height: 32px;
    border: 0;
    border-radius: 50%;
    background: #b9dbe7;
    font-size: 22px;
    line-height: 24px;
    font-family: Arial, sans-serif;
  }

  .intro {
    height: 230px;
    padding-top: 32px;
    display: flex;
    justify-content: center;
  }

  .intro-inner {
    width: 640px;
  }

  h1 {
    display: inline-block;
    margin: 0 0 20px 0;
    padding: 10px 16px 7px;
    background: #fff;
    font-size: 38px;
    line-height: 1;
    letter-spacing: -2px;
  }

  .intro p {
    width: max-content;
    max-width: 100%;
    margin: 0 0 15px 0;
    padding: 4px 7px;
    background: #fff;
    font-size: 17px;
    line-height: 1.05;
  }

  .intro a {
    color: #111;
    text-decoration: underline;
    text-decoration-style: dotted;
  }

  .striped {
    background:
      repeating-linear-gradient(
        135deg,
        rgba(111, 104, 96, .055) 0,
        rgba(111, 104, 96, .055) 2px,
        transparent 2px,
        transparent 5px
      ),
      #f5f2ee;
  }

  .control-band {
    height: 145px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .control {
    width: 640px;
