    border: 1px solid #c9bdb2;
    border-radius: 4px;
    background: #f5efeb;
    box-shadow: 0 1px 2px rgba(0,0,0,.12);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 11px;
    font-size: 16px;
  }

  .stepper {
    display: flex;
    height: 49px;
    border-radius: 4px;
    overflow: hidden;
  }

  .stepper button,
  .stepper output {
    width: 48px;
    height: 49px;
    border: 0;
    border-right: 1px solid #d4d0cb;
    display: flex;
    align-items: center;
    justify-content: center;
    font: 18px "Courier New", monospace;
  }

  .stepper button {
    background: #aed8e7;
  }

  .stepper button:last-child {
    border-right: 0;
    border-left: 1px solid #d4d0cb;
